package com.beeboee.magnot.item;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.region.*;import net.minecraft.entity.Entity;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.item.*;import net.minecraft.nbt.CompoundNBT;import net.minecraft.util.*;import net.minecraft.util.math.BlockPos;import net.minecraft.util.text.TranslationTextComponent;import net.minecraft.world.World;import net.minecraft.world.server.ServerWorld;import java.util.*;public final class FerrousTubeItem extends Item{public static final int MAX_REGION_AXIS_LENGTH=25;private static final String H="MagnotHasFirstCorner",X="MagnotFirstX",Y="MagnotFirstY",Z="MagnotFirstZ",D="MagnotFirstDimension";public FerrousTubeItem(Properties p){super(p);}@Override public ActionResultType useOn(ItemUseContext c){World w=c.getLevel();PlayerEntity p=c.getPlayer();ItemStack s=c.getItemInHand();if(p==null)return ActionResultType.PASS;if(w.isClientSide)return ActionResultType.SUCCESS;if(!(w instanceof ServerWorld))return ActionResultType.PASS;ServerWorld level=(ServerWorld)w;if(p.isShiftKeyDown()){if(first(s).isPresent()){clear(s);p.displayClientMessage(new TranslationTextComponent("message.magnot.selection_cleared"),true);}return ActionResultType.SUCCESS;}BlockPos clicked=c.getClickedPos();Optional<BlockPos>a=first(s);String dim=level.dimension().location().toString();if(!a.isPresent()||!dim.equals(dimension(s))){set(s,clicked,dim);level.playSound(null,clicked,SoundEvents.SLIME_BLOCK_PLACE,SoundCategory.BLOCKS,.5f,.85f);p.displayClientMessage(new TranslationTextComponent("message.magnot.first_corner"),true);return ActionResultType.SUCCESS;}BlockPos b=clamp(a.get(),clicked);FerrousRegion r=FerrousRegion.fromCorners(UUID.randomUUID(),a.get(),b);FerrousRegionSavedData.get(level).addRegion(r);MagnotNetwork.syncDimension(level);clear(s);level.playSound(null,b,SoundEvents.SLIME_BLOCK_PLACE,SoundCategory.BLOCKS,.5f,.95f);p.displayClientMessage(new TranslationTextComponent("message.magnot.region_created"),true);if(!p.abilities.instabuild)s.hurtAndBreak(2,p,q->q.broadcastBreakEvent(c.getHand()));return ActionResultType.SUCCESS;}@Override public void inventoryTick(ItemStack s,World w,Entity e,int slot,boolean selected){if(!w.isClientSide&&!selected&&first(s).isPresent())clear(s);}public static Optional<BlockPos> first(ItemStack s){CompoundNBT t=s.getTag();return t==null||!t.getBoolean(H)?Optional.empty():Optional.of(new BlockPos(t.getInt(X),t.getInt(Y),t.getInt(Z)));}public static BlockPos clamp(BlockPos a,BlockPos b){return new BlockPos(a.getX()+Math.max(-24,Math.min(24,b.getX()-a.getX())),a.getY()+Math.max(-24,Math.min(24,b.getY()-a.getY())),a.getZ()+Math.max(-24,Math.min(24,b.getZ()-a.getZ())));}public static boolean over(BlockPos a,BlockPos b){return Math.abs(b.getX()-a.getX())>=25||Math.abs(b.getY()-a.getY())>=25||Math.abs(b.getZ()-a.getZ())>=25;}private static String dimension(ItemStack s){return s.getTag()==null?"":s.getTag().getString(D);}private static void set(ItemStack s,BlockPos p,String d){CompoundNBT t=s.getOrCreateTag();t.putBoolean(H,true);t.putInt(X,p.getX());t.putInt(Y,p.getY());t.putInt(Z,p.getZ());t.putString(D,d);}private static void clear(ItemStack s){CompoundNBT t=s.getOrCreateTag();t.remove(H);t.remove(X);t.remove(Y);t.remove(Z);t.remove(D);}}
